type_in_namespace:
∀ {Phi : ℝ → ℝ}
    (hm : StrictMonoOn Phi (Set.Ici 0)) {k : ℕ} {x y : ℝ}
    (hx : phase_root Phi k x) (hy : phase_root Phi k y),
x = y

∀ {Phi : ℝ → ℝ}
    (hm : StrictMonoOn Phi (Set.Ici 0)) {j k : ℕ} {x y : ℝ}
    (hx : phase_root Phi j x) (hy : phase_root Phi k y),
(x < y ↔ j < k)
